import os
import ctypes
import numpy as np
from scipy.sparse.linalg._eigen.arpack import _arpacklib

_neupd = _arpacklib.dneupd_wrap
_naupd = _arpacklib.dnaupd_wrap

_HERE = os.path.dirname(os.path.abspath(__file__))

_DBL = ['tol', 'getv0_rnorm0', 'aitr_betaj', 'aitr_rnorm1', 'aitr_wnorm', 'aup2_rnorm']
_INT = {'which': 0x30, 'ido': 0x34, 'info': 0x38, 'bmat': 0x3c, 'mode': 0x40, 'n': 0x44,
        'ncv': 0x48, 'nev': 0x4c, 'shift': 0x50, 'maxiter': 0x54, 'nconv': 0x58,
        'iter': 0x5c, 'np': 0x60, 'getv0_first': 0x64, 'getv0_iter': 0x68,
        'getv0_itry': 0x6c, 'getv0_orth': 0x70, 'aitr_iter': 0x74, 'aitr_j': 0x78,
        'aitr_orth1': 0x7c, 'aitr_orth2': 0x80, 'aitr_restart': 0x84, 'aitr_step3': 0x88,
        'aitr_step4': 0x8c, 'aitr_ierr': 0x90, 'aup2_initv': 0x94, 'aup2_iter': 0x98,
        'aup2_getv0': 0x9c, 'aup2_cnorm': 0xa0, 'aup2_kplusp': 0xa4, 'aup2_nev': 0xa8,
        'aup2_nev0': 0xac, 'aup2_np0': 0xb0, 'aup2_numcnv': 0xb4, 'aup2_update': 0xb8,
        'aup2_ushift': 0xbc}

_C_SRC = r'''
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define NT 4
typedef struct {
    const int* indptr; const int* indices; const double* data;
    const double* x; double* y; int n;
    atomic_int gen; atomic_int done; atomic_int quit;
} shared_t;
typedef struct { shared_t* sh; int id; } targ_t;

static void rows(const shared_t* sh, int lo, int hi) {
    const int* ip = sh->indptr; const int* ix = sh->indices; const double* d = sh->data;
    const double* x = sh->x; double* y = sh->y;
    for (int i = lo; i < hi; i++) {
        double s = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) s += d[j] * x[ix[j]];
        y[i] = s;
    }
}
static void bounds(const shared_t* sh, int id, int* lo, int* hi) {
    /* split by nnz */
    long long nnz = sh->indptr[sh->n];
    long long t0 = nnz * id / NT, t1 = nnz * (id + 1) / NT;
    int a = 0, b = sh->n;
    while (a < b) { int m = (a + b) / 2; if (sh->indptr[m] < t0) a = m + 1; else b = m; }
    *lo = a; a = 0; b = sh->n;
    while (a < b) { int m = (a + b) / 2; if (sh->indptr[m] < t1) a = m + 1; else b = m; }
    *hi = (id == NT - 1) ? sh->n : a;
    if (id == 0) *lo = 0;
}
static void* worker(void* p) {
    targ_t* t = (targ_t*)p; shared_t* sh = t->sh; int seen = 0, lo, hi;
    bounds(sh, t->id, &lo, &hi);
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&sh->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&sh->quit, memory_order_relaxed)) return 0;
            __builtin_ia32_pause();
        }
        seen = g;
        rows(sh, lo, hi);
        atomic_fetch_add_explicit(&sh->done, 1, memory_order_release);
    }
}
int run(void* fp, char* state, double* resid, double* v, int ldv, int* ipntr,
        double* workd, double* workl, int n, const int* indptr, const int* indices,
        const double* data)
{
    naupd_t f = (naupd_t)fp;
    int* ido = (int*)(state + 0x34);
    shared_t sh; sh.indptr = indptr; sh.indices = indices; sh.data = data; sh.n = n;
    atomic_init(&sh.gen, 0); atomic_init(&sh.done, 0); atomic_init(&sh.quit, 0);
    pthread_t th[NT]; targ_t ta[NT]; int nth = 0, lo0, hi0, gen = 0, ret;
    bounds(&sh, 0, &lo0, &hi0);
    for (int i = 1; i < NT; i++) {
        ta[i].sh = &sh; ta[i].id = i;
        if (pthread_create(&th[i], 0, worker, &ta[i]) != 0) break;
        nth++;
    }
    if (nth != NT - 1) { lo0 = 0; hi0 = n; }
    for (;;) {
        f(state, resid, v, ldv, ipntr, workd, workl);
        int c = *ido;
        if (c == 1 || c == 5) {
            sh.x = workd + ipntr[0]; sh.y = workd + ipntr[1];
            if (nth == NT - 1) {
                atomic_store_explicit(&sh.done, 0, memory_order_relaxed);
                atomic_store_explicit(&sh.gen, ++gen, memory_order_release);
                rows(&sh, lo0, hi0);
                while (atomic_load_explicit(&sh.done, memory_order_acquire) != nth) __builtin_ia32_pause();
            } else {
                rows(&sh, 0, n);
            }
        } else if (c == 2) {
            memmove(workd + ipntr[1], workd + ipntr[0], sizeof(double) * n);
        } else { ret = c; break; }
    }
    atomic_store(&sh.quit, 1);
    for (int i = 1; i <= nth; i++) pthread_join(th[i], 0);
    return ret;
}
'''

def _rebind(ar):
    """Point the private ARPACK copy's dtrevc/dlarf imports at Accelerate's
    legacy entry points (same arithmetic, far less allocation overhead).
    Only done when the binary layout matches what we verified."""
    try:
        base = ctypes.cast(ar.ARNAUD_dnaupd, ctypes.c_void_p).value - 0xd240
        acc = ctypes.CDLL('/System/Library/Frameworks/Accelerate.framework/Accelerate')
        for name, slot in (('dtrevc', 0x25220), ('dlarf', 0x251b8)):
            p = ctypes.c_void_p.from_address(base + slot)
            cur = ctypes.cast(getattr(acc, name + '$NEWLAPACK'), ctypes.c_void_p).value
            if p.value != cur:
                continue
            p.value = ctypes.cast(getattr(acc, name + '_'), ctypes.c_void_p).value
    except Exception:
        pass


_lib = None
_fp = None


def _load():
    global _lib, _fp
    if _lib is not None:
        return _lib is not False
    try:
        so = os.path.join(_HERE, "_arloop.so")
        if not os.path.exists(so):
            src = os.path.join(_HERE, "_arloop.c")
            with open(src, "w") as f:
                f.write(_C_SRC)
            r = os.system(f"cc -O2 -fPIC -shared -ffp-contract=off -o '{so}' '{src}' 2>/dev/null")
            if r != 0:
                raise RuntimeError
        lib = ctypes.CDLL(so)
        lib.run.restype = ctypes.c_int
        # Private copy of scipy's ARPACK library so that rebinding its LAPACK
        # imports does not affect anything else in the process.
        cp = os.path.join(_HERE, "_arpack_private.so")
        if not os.path.exists(cp):
            import shutil
            shutil.copyfile(_arpacklib.__file__, cp)
        ar = ctypes.CDLL(cp)
        _fp = ctypes.cast(ar.ARNAUD_dnaupd, ctypes.c_void_p).value
        _rebind(ar)
        _lib = lib
        return True
    except Exception:
        _lib = False
        return False


_load()


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        if A.dtype != np.float64 or A.format != "csr" or not _load():
            from reference import Task
            return Task().solve(problem)
        n = A.shape[0]
        ncv = min(max(2 * k + 1, 20), n)
        indptr = np.ascontiguousarray(A.indptr, dtype=np.int32)
        indices = np.ascontiguousarray(A.indices, dtype=np.int32)
        data = np.ascontiguousarray(A.data, dtype=np.float64)

        st = np.zeros(0xc0, dtype=np.uint8)
        dv = st.view(np.float64)
        iv = st.view(np.int32)
        init = {'info': 1, 'maxiter': n * 200, 'mode': 1, 'n': n, 'ncv': ncv,
                'nev': k, 'shift': 1, 'which': 0, 'bmat': 0}
        for key, val in init.items():
            iv[_INT[key] // 4] = val
        resid = np.ones(n, dtype=np.float64)
        v = np.zeros((n, ncv), np.float64)
        ipntr = np.zeros(14, dtype=np.int32)
        workd = np.zeros(3 * n, dtype=np.float64)
        workl = np.zeros(3 * ncv * (ncv + 2), dtype=np.float64)
        P = ctypes.c_void_p
        ido = _lib.run(P(_fp), P(st.ctypes.data), P(resid.ctypes.data), P(v.ctypes.data),
                       ctypes.c_int(n), P(ipntr.ctypes.data), P(workd.ctypes.data),
                       P(workl.ctypes.data), ctypes.c_int(n), P(indptr.ctypes.data),
                       P(indices.ctypes.data), P(data.ctypes.data))
        info = int(iv[_INT['info'] // 4])
        if ido != 99 or info != 0:
            from reference import Task
            return Task().solve(problem)
        d = {}
        for i, key in enumerate(_DBL):
            d[key] = float(dv[i])
        for key, off in _INT.items():
            d[key] = int(iv[off // 4])
        d['info'] = 0
        sselect = np.zeros(ncv, dtype=np.int32)
        workev = np.zeros(3 * ncv, np.float64)
        dr = np.zeros(k + 1); di = np.zeros(k + 1)
        zr = np.zeros((n, k + 1), dtype=np.float64, order='F')
        _neupd(d, 1, 0, sselect, dr, di, zr, 0.0, 0.0, workev, resid, v, ipntr, workd, workl)
        if d['info'] != 0:
            from reference import Task
            return Task().solve(problem)
        nret = d['nconv']
        ev = dr + 1.0j * di
        z = zr.astype(np.complex128)
        i = 0
        while i <= k:
            if abs(ev[i].imag) != 0:
                if i < k:
                    z[:, i] = zr[:, i] + 1.0j * zr[:, i + 1]
                    z[:, i + 1] = z[:, i].conjugate()
                    i += 1
                else:
                    nret -= 1
            i += 1
        if nret <= k:
            ev = ev[:nret]; z = z[:, :nret]
        else:
            ind = np.argsort(abs(ev))[-k:][::-1]
            ev = ev[ind]; z = z[:, ind]
        order = sorted(range(len(ev)), key=lambda j: -np.abs(ev[j]))
        return [z[:, j] for j in order]

