#include <immintrin.h>
#include <stdlib.h>
#include <string.h>
/* SELL-4: for group g of 4 rows, length L[g]; arrays packed column-major: val[off+4*t+r], col[...] , mask */
void ref_mv(int n,const int*ip,const int*ix,const double*d,const double*x,double*y){
  for(int i=0;i<n;i++){double s=0.0;for(int j=ip[i];j<ip[i+1];j++)s+=d[j]*x[ix[j]];y[i]=s;}
}
int pack(int n,const int*ip,const int*ix,const double*d,int*goff,int*glen,double*val,long long*col){
  int ng=(n+3)/4, off=0;
  for(int g=0;g<ng;g++){
    int L=0; for(int r=0;r<4;r++){int i=4*g+r; if(i<n){int l=ip[i+1]-ip[i]; if(l>L)L=l;}}
    goff[g]=off; glen[g]=L;
    for(int t=0;t<L;t++) for(int r=0;r<4;r++){
      int i=4*g+r; int k=off+4*t+r;
      if(i<n && t<ip[i+1]-ip[i]){val[k]=d[ip[i]+t]; col[k]=ix[ip[i]+t];}
      else {val[k]=0.0; col[k]=-1;}
    }
    off+=4*L;
  }
  return off;
}
void sell_mv(int n,int ng,const int*goff,const int*glen,const double*val,const long long*col,const double*x,double*y){
  for(int g=0;g<ng;g++){
    __m256d s=_mm256_setzero_pd();
    const double*v=val+goff[g]; const long long*c=col+goff[g];
    for(int t=0;t<glen[g];t++){
      __m256i ci=_mm256_loadu_si256((const __m256i*)(c+4*t));
      __m256i m=_mm256_cmpgt_epi64(ci,_mm256_set1_epi64x(-1));
      __m256d xv=_mm256_mask_i64gather_pd(_mm256_setzero_pd(),x,ci,_mm256_castsi256_pd(m),8);
      __m256d p=_mm256_mul_pd(_mm256_loadu_pd(v+4*t),xv);
      __m256d ns=_mm256_add_pd(s,p);
      s=_mm256_blendv_pd(s,ns,_mm256_castsi256_pd(m));
    }
    if(4*g+4<=n) _mm256_storeu_pd(y+4*g,s);
    else {double tmp[4]; _mm256_storeu_pd(tmp,s); for(int r=0;4*g+r<n;r++) y[4*g+r]=tmp[r];}
  }
}
