void mv1(int n,const int*ip,const int*ix,const double*d,const double*x,double*y){
  for(int i=0;i<n;i++){double s=0.0;for(int j=ip[i];j<ip[i+1];j++)s+=d[j]*x[ix[j]];y[i]=s;}
}
#define R 8
void mv8(int n,const int*ip,const int*ix,const double*d,const double*x,double*y){
  int i=0;
  for(;i+R<=n;i+=R){
    double s[R]; int a[R],e[R]; int m=1<<30;
    for(int r=0;r<R;r++){s[r]=0.0;a[r]=ip[i+r];e[r]=ip[i+r+1]; if(e[r]-a[r]<m)m=e[r]-a[r];}
    for(int t=0;t<m;t++){
      #pragma clang loop unroll(full)
      for(int r=0;r<R;r++) s[r]+=d[a[r]+t]*x[ix[a[r]+t]];
    }
    for(int r=0;r<R;r++){double q=s[r];for(int j=a[r]+m;j<e[r];j++)q+=d[j]*x[ix[j]];y[i+r]=q;}
  }
  for(;i<n;i++){double s=0.0;for(int j=ip[i];j<ip[i+1];j++)s+=d[j]*x[ix[j]];y[i]=s;}
}
void bench(int which,int reps,int n,const int*ip,const int*ix,const double*d,const double*x,double*y){
  for(int k=0;k<reps;k++){ if(which) mv8(n,ip,ix,d,x,y); else mv1(n,ip,ix,d,x,y);}
}
