    while(lastv>0 && v[i-1]==0.0){lastv--; i-=inc;}
    if(left){ /* iladlc(lastv,n,C) */
      if(n==0) lastc=n; else if(C[(long)(n-1)*ld]!=0.0||C[lastv-1+(long)(n-1)*ld]!=0.0) lastc=n;
      else { lastc=0; for(int j=n;j>=1;j--){int nz=0; for(int r=0;r<lastv;r++) if(C[r+(long)(j-1)*ld]!=0.0){nz=1;break;} if(nz){lastc=j;break;}} }
