#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
#define NT 4
typedef struct {
    const int* indptr; const int* indices; const double* data;
    const double* x; double* y; int n;
    atomic_int gen; atomic_int done; atomic_int quit;
} shared_t;
typedef struct { shared_t* sh; int id; } targ_t;

static void rows(const shared_t* sh, int lo, int hi) {
    const int* ip = sh->indptr; const int* ix = sh->indices; const double* d = sh->data;
    const double* x = sh->x; double* y = sh->y;
    for (int i = lo; i < hi; i++) {
        double s = 0.0;
        for (int j = ip[i]; j < ip[i+1]; j++) s += d[j] * x[ix[j]];
        y[i] = s;
    }
}
static void bounds(const shared_t* sh, int id, int* lo, int* hi) {
    /* split by nnz */
    long long nnz = sh->indptr[sh->n];
    long long t0 = nnz * id / NT, t1 = nnz * (id + 1) / NT;
    int a = 0, b = sh->n;
    while (a < b) { int m = (a + b) / 2; if (sh->indptr[m] < t0) a = m + 1; else b = m; }
    *lo = a; a = 0; b = sh->n;
    while (a < b) { int m = (a + b) / 2; if (sh->indptr[m] < t1) a = m + 1; else b = m; }
    *hi = (id == NT - 1) ? sh->n : a;
    if (id == 0) *lo = 0;
}
static void* worker(void* p) {
    targ_t* t = (targ_t*)p; shared_t* sh = t->sh; int seen = 0, lo, hi;
    bounds(sh, t->id, &lo, &hi);
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&sh->gen, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&sh->quit, memory_order_relaxed)) return 0;
            __builtin_ia32_pause();
        }
        seen = g;
        rows(sh, lo, hi);
        atomic_fetch_add_explicit(&sh->done, 1, memory_order_release);
    }
}
int run(void* fp, char* state, double* resid, double* v, int ldv, int* ipntr,
        double* workd, double* workl, int n, const int* indptr, const int* indices,
        const double* data)
{
    naupd_t f = (naupd_t)fp;
    int* ido = (int*)(state + 0x34);
    shared_t sh; sh.indptr = indptr; sh.indices = indices; sh.data = data; sh.n = n;
    atomic_init(&sh.gen, 0); atomic_init(&sh.done, 0); atomic_init(&sh.quit, 0);
    pthread_t th[NT]; targ_t ta[NT]; int nth = 0, lo0, hi0, gen = 0, ret;
    bounds(&sh, 0, &lo0, &hi0);
    for (int i = 1; i < NT; i++) {
        ta[i].sh = &sh; ta[i].id = i;
        if (pthread_create(&th[i], 0, worker, &ta[i]) != 0) break;
        nth++;
    }
    if (nth != NT - 1) { lo0 = 0; hi0 = n; }
    for (;;) {
        f(state, resid, v, ldv, ipntr, workd, workl);
        int c = *ido;
        if (c == 1 || c == 5) {
            sh.x = workd + ipntr[0]; sh.y = workd + ipntr[1];
            if (nth == NT - 1) {
                atomic_store_explicit(&sh.done, 0, memory_order_relaxed);
                atomic_store_explicit(&sh.gen, ++gen, memory_order_release);
                rows(&sh, lo0, hi0);
                while (atomic_load_explicit(&sh.done, memory_order_acquire) != nth) __builtin_ia32_pause();
            } else {
                rows(&sh, 0, n);
            }
        } else if (c == 2) {
            memmove(workd + ipntr[1], workd + ipntr[0], sizeof(double) * n);
        } else { ret = c; break; }
    }
    atomic_store(&sh.quit, 1);
    for (int i = 1; i <= nth; i++) pthread_join(th[i], 0);
    return ret;
}
