#include <math.h>
/* dgemv 'T' variants: y[j] = beta*y[j] + alpha*dot(A[:,j],x); m small */
void gT(int var,int m,int n,double a,const double*A,int ld,const double*x,double b,double*y){
  for(int j=0;j<n;j++){const double*c=A+(long)j*ld; double s=0;
    if(var&1){ s=0; for(int i=0;i<m;i++) s=fma(c[i],x[i],s);} else { s=0; for(int i=0;i<m;i++) s+=c[i]*x[i]; }
    double yy = (b==0.0)?0.0:b*y[j];
    if(var&2) y[j]=fma(a,s,yy); else y[j]=yy+a*s; }
}
/* dgemv 'N': y = beta*y + alpha*A x */
void gN(int var,int m,int n,double a,const double*A,int ld,const double*x,double b,double*y){
  for(int i=0;i<m;i++) y[i]=(b==0.0)?0.0:b*y[i];
  if(var==0) for(int j=0;j<n;j++){double t=a*x[j];for(int i=0;i<m;i++)y[i]+=t*A[i+(long)j*ld];}
  if(var==1) for(int j=0;j<n;j++){double t=a*x[j];for(int i=0;i<m;i++)y[i]=fma(t,A[i+(long)j*ld],y[i]);}
  if(var==2) for(int i=0;i<m;i++){double s=0;for(int j=0;j<n;j++)s=fma(A[i+(long)j*ld],x[j],s); y[i]=fma(a,s,y[i]);}
  if(var==3) for(int i=0;i<m;i++){double s=0;for(int j=0;j<n;j++)s+=A[i+(long)j*ld]*x[j]; y[i]+=a*s;}
}
void ger(int var,int m,int n,double a,const double*x,const double*y,double*A,int ld){
  for(int j=0;j<n;j++) for(int i=0;i<m;i++){double*p=A+i+(long)j*ld;
    if(var==0) *p=fma(a*y[j],x[i],*p);
    if(var==1) *p=*p+(a*y[j])*x[i];
    if(var==2) *p=fma(a*x[i],y[j],*p);
    if(var==3) *p=*p+(a*x[i])*y[j];
  }
}
