#include <math.h>
void gN(int var,int m,int n,const double*A,int ld,const double*x,double*y){
  for(int i=0;i<m;i++){ const double*r=A+i; double s;
    if(var==0){ s=r[0]*x[0]; for(int j=1;j<n;j++) s=fma(r[(long)j*ld],x[j],s);}
    else if(var==1){ s=r[0]*x[0]; for(int j=1;j<n;j++) s=s+r[(long)j*ld]*x[j];}
    else if(var==2){ s=x[0]*r[0]; for(int j=1;j<n;j++) s=fma(x[j],r[(long)j*ld],s);}
    else if(var==3){ /* reverse */ s=r[(long)(n-1)*ld]*x[n-1]; for(int j=n-2;j>=0;j--) s=fma(r[(long)j*ld],x[j],s);}
    else { /* pairwise 2 */ if(n==1) s=r[0]*x[0]; else if(n==2) s=fma(r[ld],x[1],r[0]*x[0]); else { s=fma(r[ld],x[1],r[0]*x[0]); s=fma(r[2*(long)ld],x[2],s);} }
    y[i]=s; }
}
