void my_dcopy(const int*N,const double*x,const int*incx,double*y,const int*incy){
  int n=*N,ix=*incx,iy=*incy; if(n<=0)return;
  if(ix==1&&iy==1){memmove(y,x,sizeof(double)*n);return;}
  int kx= ix<0?(1-n)*ix:0, ky= iy<0?(1-n)*iy:0;
  for(int i=0;i<n;i++) y[ky+i*iy]=x[kx+i*ix];
